-            m(m), n(n), k(k) {
+            m(m), n(n), k(k), repeat_ids(repeat_ids) {
             GGML_ASSERT(n_used <= n_mats);
         }

@@ -4487,7 +4509,7 @@ struct test_mul_mat_id : public test_case {
     }

     void initialize_tensors(ggml_context * ctx) override {
-        init_mul_mat_id_tensors(ctx, n_mats);
+        init_mul_mat_id_tensors(ctx, n_mats, repeat_ids);
     }
 };

@@ -9036,6 +9058,17 @@ static std::vector<std::unique_ptr<test_case>> make_test_cases_eval() {
     test_cases.emplace_back(new test_mul_mat_id_fusion(GGML_TYPE_F16, GGML_TYPE_F32, 16, 16, false, 32, 32, 32, 3));

     // gpt-oss issue with Vulkan mmq_id
